export namespace FollowMode {
    let FOLLOW: string;
    let DEADZONE: string;
    let LOCKED: string;
}
/**
 * PlatformerCamera - Flexible 2D camera for platformer games
 *
 * A highly configurable camera designed for 2D platformer games.
 * Supports multiple follow modes per axis for different game styles.
 *
 * **Follow Modes:**
 * - `FollowMode.FOLLOW` - Smooth follow with velocity-based lookahead
 * - `FollowMode.DEADZONE` - Only move when target exits the deadzone
 * - `FollowMode.LOCKED` - Fixed position on that axis
 *
 * **Screen Anchor:**
 * Use `anchor` to position where the target rests on screen (0-1 normalized).
 * - `(0.5, 0.5)` = center (default)
 * - `(0.25, 0.5)` = 25% from left edge (Mario-style)
 * - `(0.5, 0.75)` = 75% from bottom (vertical climber)
 *
 * **Mario-Style Features:**
 * - `anchor: (0.25, 0.5)` - Target on left side of screen
 * - `lockBackward: true` - Camera only scrolls right, never backward
 * - `edgeEvents: { left: true }` - Dispatch events when target hits viewport edge
 *
 * **Use Cases:**
 * - Side-scroller (Mario): `followModeX: DEADZONE, anchor: (0.25, 0.5), lockBackward: true`
 * - Vertical climber: `followModeY: FOLLOW, anchor: (0.5, 0.25)`
 * - Top-down: `followModeX: FOLLOW, followModeY: FOLLOW`
 * - Single-screen: `followModeX: LOCKED, followModeY: LOCKED`
 *
 * @class PlatformerCamera
 * @extends OrthographicPhysicsCamera
 * @short Flexible 2D camera for platformer games with configurable follow modes.
 * @category Camera
 * @tags Physics, Camera, 2D, Platformer, Orthographic, WebGPU, WebGL
 *
 * @example
 * ```js
 * import { PlatformerCamera, FollowMode } from '@three-blocks/pro';
 *
 * // Mario-style side-scroller
 * const camera = new PlatformerCamera(physics, {
 *   target: playerMesh,
 *   zoom: 10,
 *   anchor: new THREE.Vector2(0.25, 0.5),  // Player on left side
 *   followModeX: FollowMode.DEADZONE,
 *   followModeY: FollowMode.DEADZONE,
 *   deadzone: new THREE.Vector2(1, 2),
 *   lookahead: new THREE.Vector2(3, 0),
 *   damping: 5,
 *   lockBackward: true,
 *   edgeEvents: { left: true, bottom: true },
 * });
 *
 * // Handle player hitting viewport boundary
 * camera.addEventListener('boundaryHit', (event) => {
 *   if (event.edge === 'left') {
 *     playerBody.teleport(new THREE.Vector3(event.bounds.min.x, event.position.y, 0));
 *   }
 * });
 *
 * // In animation loop
 * camera.update(delta);
 * renderer.render(scene, camera);
 * ```
 */
export class PlatformerCamera extends OrthographicPhysicsCamera {
    /**
     * Create a PlatformerCamera.
     *
     * @param {Object} physics - Physics instance
     * @param {Object} [options={}] - Camera options
     * @param {THREE.Object3D} [options.target] - Target object to follow
     * @param {number} [options.zoom=10] - Visible area half-height in world units
     * @param {THREE.Vector2} [options.anchor] - Screen anchor position (0-1). Where target rests on screen. Default: (0.5, 0.5) = center
     * @param {string} [options.followModeX='follow'] - X-axis follow mode: FollowMode.FOLLOW, DEADZONE, or LOCKED
     * @param {string} [options.followModeY='deadzone'] - Y-axis follow mode: FollowMode.FOLLOW, DEADZONE, or LOCKED
     * @param {THREE.Vector3} [options.offset] - Offset from target position in world units
     * @param {THREE.Vector2} [options.deadzone] - Deadzone half-sizes in world units (default: 2, 1.5)
     * @param {THREE.Vector2} [options.lookahead] - Velocity-based lookahead offsets (default: 3, 0)
     * @param {number} [options.lookaheadSpeed=3] - Lookahead transition speed
     * @param {THREE.Box2} [options.bounds] - Camera bounds (level edges)
     * @param {number} [options.damping=3] - Camera movement smoothing factor
     * @param {number} [options.distance=50] - Camera Z position (distance from XY plane)
     * @param {number} [options.near=0.1] - Near clipping plane
     * @param {number} [options.far=1000] - Far clipping plane
     * @param {boolean} [options.lockBackward=false] - Camera only scrolls forward (positive X), never backward
     * @param {Object} [options.edgeEvents] - Emit 'boundaryHit' events when target exceeds viewport edges
     * @param {boolean} [options.edgeEvents.left=false] - Emit event when target goes past left edge
     * @param {boolean} [options.edgeEvents.right=false] - Emit event when target goes past right edge
     * @param {boolean} [options.edgeEvents.top=false] - Emit event when target goes past top edge
     * @param {boolean} [options.edgeEvents.bottom=false] - Emit event when target goes past bottom edge
     */
    constructor(physics: any, options?: {
        target?: THREE.Object3D;
        zoom?: number;
        anchor?: THREE.Vector2;
        followModeX?: string;
        followModeY?: string;
        offset?: THREE.Vector3;
        deadzone?: THREE.Vector2;
        lookahead?: THREE.Vector2;
        lookaheadSpeed?: number;
        bounds?: THREE.Box2;
        damping?: number;
        distance?: number;
        near?: number;
        far?: number;
        lockBackward?: boolean;
        edgeEvents?: {
            left?: boolean;
            right?: boolean;
            top?: boolean;
            bottom?: boolean;
        };
    });
    /**
     * Screen anchor position (0-1 normalized).
     * Defines where the target rests on screen.
     * - (0.5, 0.5) = center
     * - (0.25, 0.5) = 25% from left (Mario-style)
     * @type {THREE.Vector2}
     */
    anchor: THREE.Vector2;
    /**
     * X-axis follow mode.
     * @type {string}
     */
    followModeX: string;
    /**
     * Y-axis follow mode.
     * @type {string}
     */
    followModeY: string;
    /**
     * Offset from target position in world units.
     * Use to position camera focus above/below target center.
     * @type {THREE.Vector3}
     */
    offset: THREE.Vector3;
    /**
     * Deadzone half-sizes in world units.
     * Target can move freely within deadzone without camera movement.
     * @type {THREE.Vector2}
     */
    deadzone: THREE.Vector2;
    /**
     * Velocity-based lookahead offsets.
     * Camera looks ahead in the direction of movement.
     * @type {THREE.Vector2}
     */
    lookahead: THREE.Vector2;
    /**
     * Lookahead transition speed.
     * Higher values = faster transition to lookahead position.
     * @type {number}
     */
    lookaheadSpeed: number;
    /**
     * Camera bounds (level edges).
     * Camera will not move outside these bounds.
     * @type {THREE.Box2|null}
     */
    bounds: THREE.Box2 | null;
    /**
     * Camera movement smoothing factor.
     * Higher values = faster camera movement.
     * @type {number}
     */
    damping: number;
    /**
     * Camera Z position (distance from XY plane).
     * @type {number}
     */
    distance: number;
    /**
     * Lock backward scrolling on X axis (Mario-style one-way scrolling).
     * When enabled, camera only scrolls in positive X direction.
     * @type {boolean}
     */
    lockBackwardX: boolean;
    /**
     * Lock backward scrolling on Y axis.
     * When enabled, camera only scrolls in positive Y direction.
     * @type {boolean}
     */
    lockBackwardY: boolean;
    /**
     * Edge events configuration.
     * When set, dispatches 'boundaryHit' events when target exceeds viewport edges.
     * @type {Object|null}
     */
    edgeEvents: any | null;
    /**
     * Reusable Box2 for player bounds (avoid allocations).
     * @type {THREE.Box2}
     * @private
     */
    private _playerBounds;
    /**
     * Current lookahead offset (smoothly interpolated).
     * @type {THREE.Vector2}
     * @private
     */
    private _currentLookahead;
    /**
     * Target lookahead offset (what we're interpolating toward).
     * @type {THREE.Vector2}
     * @private
     */
    private _targetLookahead;
    /**
     * Desired camera position before damping.
     * @type {THREE.Vector3}
     * @private
     */
    private _desiredPosition;
    /**
     * Whether this is the first update (skip interpolation).
     * @type {boolean}
     * @private
     */
    private _firstUpdate;
    set targetOffset(v: THREE.Vector3);
    /** @deprecated Use `offset` instead */
    get targetOffset(): THREE.Vector3;
    set zOffset(v: number);
    /** @deprecated Use `distance` instead */
    get zOffset(): number;
    set forwardOnly(v: boolean);
    /** @deprecated Use `lockBackwardX` instead */
    get forwardOnly(): boolean;
    set lockBackward(v: boolean);
    /** @deprecated Use `lockBackwardX` instead */
    get lockBackward(): boolean;
    set constrainPlayer(v: any);
    /** @deprecated Use `edgeEvents` instead */
    get constrainPlayer(): any;
    set lookaheadDamping(v: number);
    /** @deprecated Use `lookaheadSpeed` instead */
    get lookaheadDamping(): number;
    /**
     * Get viewport half-width in world units.
     * @returns {number} Half-width
     * @private
     */
    private _getHalfWidth;
    /**
     * Get viewport half-height in world units.
     * @returns {number} Half-height
     * @private
     */
    private _getHalfHeight;
    /**
     * Calculate lookahead based on target velocity.
     * Sets target lookahead which is then smoothly interpolated.
     *
     * @param {number} delta - Time delta in seconds
     * @private
     */
    private _calculateLookahead;
    /**
     * Apply deadzone logic to get camera Y position.
     * Uses anchor.y to offset the reference point.
     *
     * @param {number} targetY - Target Y position
     * @returns {number} Camera Y position after deadzone
     * @private
     */
    private _applyDeadzoneY;
    /**
     * Apply deadzone logic to get camera X position.
     * Uses anchor.x to offset the reference point.
     * When `lockBackward` is true, camera only moves when player exits right side.
     *
     * @param {number} targetX - Target X position
     * @returns {number} Camera X position after deadzone
     * @private
     */
    private _applyDeadzoneX;
    /**
     * Get the current player-allowed bounds based on camera viewport.
     * Returns the Box2 representing where the player can be without triggering boundary events.
     *
     * @returns {THREE.Box2|null} Player bounds in world coordinates, or null if edgeEvents not set
     */
    getPlayerBounds(): THREE.Box2 | null;
    /**
     * Check if target exceeds player bounds and dispatch events.
     * Called at the end of update() after camera position is finalized.
     *
     * @private
     */
    private _checkPlayerBounds;
    /**
     * Apply camera bounds to position.
     *
     * @param {THREE.Vector3} position - Position to clamp
     * @private
     */
    private _applyBounds;
    /**
     * Calculate the anchor-adjusted initial camera position.
     * Positions camera so target appears at the anchor point on screen.
     *
     * @param {THREE.Vector3} targetPos - Target position
     * @returns {THREE.Vector3} Adjusted camera position
     * @private
     */
    private _getAnchorAdjustedPosition;
    /**
     * Immediately snap camera to target position.
     * Use when teleporting the player or resetting the level.
     *
     * @returns {this} For chaining
     */
    snapToTarget(): this;
    /**
     * Set camera bounds.
     *
     * @param {THREE.Box2} bounds - Bounds object
     * @returns {this} For chaining
     */
    setBounds(bounds: THREE.Box2): this;
    /**
     * Clear camera bounds.
     *
     * @returns {this} For chaining
     */
    clearBounds(): this;
}
